parameters.jsCode:
// Recopilar todas las respuestas de la Ronda 1
const items = $input.all();

const especialistas = [
  { nombre: 'Dra. Ana Valverde', rol: 'Radióloga de Mama (Moderadora)' },
  { nombre: 'Dr. Carlos Mendoza', rol: 'Cirujano Oncólogo de Mama' },
  { nombre: 'Dra. Patricia Roldán', rol: 'Oncóloga Médica' },
  { nombre: 'Dr. Rubén Castillo', rol: 'Patólogo Especialista' },
  { nombre: 'Dra. Sofía Herrera', rol: 'Ginecóloga Mastóloga' }
];

let discusion_r1 = '=== RONDA 1: VALORACIONES INICIALES ===\n\n';
const respuestas_r1 = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const especialista = especialistas[i] || { nombre: `Especialista ${i+1}`, rol: 'No definido' };

  let respuesta = '';
  if (item.json && item.json.content && item.json.content[0]) {
    respuesta = item.json.content[0].text || 'Sin respuesta';
  } else if (item.json && item.json.error) {
    respuesta = `ERROR: ${JSON.stringify(item.json.error)}`;
  }

  respuestas_r1.push({
    especialista: especialista.nombre,
    rol: especialista.rol,
    respuesta: respuesta
  });

  discusion_r1 += `--- ${especialista.nombre} (${especialista.rol}) ---\n${respuesta}\n\n`;
}

return [{
  json: {
    discusion_ronda1: discusion_r1,
    respuestas_r1: respuestas_r1,
    caso_clinico: $('Configurar Caso Clinico').first().json.caso_clinico,
    anthropic_api_key: $('Configurar Caso Clinico').first().json.anthropic_api_key,
    modelo_debate: $('Configurar Caso Clinico').first().json.modelo_debate,
    modelo_sintesis: $('Configurar Caso Clinico').first().json.modelo_sintesis
  }
}];

